(async () => {
  const want = ["Contra", "Super Mario Bros. 3", "Mega Man 2", "Ninja Gaiden", "Castlevania III"];
  const norm = s => s.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const key  = s => s.toLowerCase().replace(/[^a-z0-9]+/g,'');
  const html = await (await fetch('https://retroachievements.org/gameList.php?system=7')).text();
  const doc = new DOMParser().parseFromString(html,'text/html');
  const byName = {}, byKey = {};
  doc.querySelectorAll('a[href*="/game/"]').forEach(a => {
    const m = a.getAttribute('href').match(/\/game\/(\d+)/); if (!m) return;
    const t = (a.textContent||'').trim(); if (!t) return;
    const n = norm(t), k = key(t);
    if (!(n in byName)) byName[n] = m[1];
    if (!(k in byKey)) byKey[k] = m[1];
  });
  const findAch = (n,d) => {
    if (!n || typeof n !== 'object' || d > 8) return null;
    if (Array.isArray(n) && n.length && n[0] && typeof n[0] === 'object' && 'title' in n[0] && 'points' in n[0]) return n;
    for (const k in n) { const r = findAch(n[k], d+1); if (r) return r; }
    return null;
  };
  const out = {};
  for (const t of want) {
    const id = byName[norm(t)] || byKey[key(t)];
    if (!id) { out[t] = { missing: true }; continue; }
    const h = await (await fetch('https://retroachievements.org/game/' + id)).text();
    const d2 = new DOMParser().parseFromString(h, 'text/html');
    const blob = d2.querySelector('script[type="application/json"]');
    if (!blob) { out[t] = { raId: id, nojson: true }; continue; }
    let j; try { j = JSON.parse(blob.textContent); } catch (e) { out[t] = { raId: id, badjson: true }; continue; }
    const arr = findAch(j, 0) || [];
    out[t] = { raId: Number(id), n: arr.length, ach: arr.map(a => ({ id: a.id, title: a.title, desc: a.description, points: a.points, ratio: a.pointsWeighted, type: a.type || '', awarded: a.unlocksTotal || 0 })) };
  }
  return JSON.stringify(out);
})()
